CREATE TABLE webhook_event (id BIGINT AUTO_INCREMENT PRIMARY KEY,event_uuid VARCHAR(128) NOT NULL UNIQUE,event_type VARCHAR(64) NOT NULL,payload_digest CHAR(64) NOT NULL,received_at TIMESTAMP(6) NOT NULL,processed BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE review_task (id BIGINT AUTO_INCREMENT PRIMARY KEY,idempotency_key VARCHAR(256) NOT NULL UNIQUE,project_id BIGINT NOT NULL,mr_iid BIGINT NOT NULL,head_sha VARCHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,complexity VARCHAR(16),attempt INT NOT NULL DEFAULT 0,error_message VARCHAR(1000),queued_at TIMESTAMP(6) NOT NULL,finished_at TIMESTAMP(6));
CREATE TABLE review_issue (id BIGINT AUTO_INCREMENT PRIMARY KEY,task_id BIGINT NOT NULL,fingerprint CHAR(64) NOT NULL,rule_id VARCHAR(128) NOT NULL,severity VARCHAR(16) NOT NULL,title VARCHAR(300) NOT NULL,file_path VARCHAR(500) NOT NULL,start_line INT NOT NULL,end_line INT NOT NULL,evidence TEXT NOT NULL,impact TEXT NOT NULL,suggestion TEXT NOT NULL,confidence DECIMAL(5,4) NOT NULL,UNIQUE(task_id,fingerprint),CONSTRAINT fk_issue_task FOREIGN KEY(task_id) REFERENCES review_task(id));
CREATE TABLE review_feedback (id BIGINT AUTO_INCREMENT PRIMARY KEY,issue_id BIGINT NOT NULL,feedback_type VARCHAR(40) NOT NULL,reason VARCHAR(1000),operator_id VARCHAR(128),created_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_feedback_issue FOREIGN KEY(issue_id) REFERENCES review_issue(id));
